const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    const depok = ee.Geometry.Point([106.82, -6.39]);
    const areaOfInterest = depok.buffer(5000); // 5km buffer around Depok
    const year1 = 1990;
    const year2 = 2019;
    const startDate1 = ee.Date.fromYMD(year1, 1, 1);
    const endDate1 = ee.Date.fromYMD(year1, 12, 31);
    const startDate2 = ee.Date.fromYMD(year2, 1, 1);
    const endDate2 = ee.Date.fromYMD(year2, 12, 31);

    // 2. Data Acquisition & Cloud Masking Functions
    const cloudMaskL457 = (image) => {
        const qa = image.select('QA_PIXEL');
        const cloud = qa.bitwiseAnd(1 << 5).or(qa.bitwiseAnd(1 << 7));
        return image.updateMask(cloud.not());
    };

    const cloudMaskL8 = (image) => {
        const qa = image.select('QA_PIXEL');
        const cloud = qa.bitwiseAnd(1 << 3).or(qa.bitwiseAnd(1 << 5));
        return image.updateMask(cloud.not());
    };

    const addNdviL5 = (image) => {
        return image.addBands(image.normalizedDifference(['B4', 'B3']).rename('NDVI'));
    };

    const addNdviL8 = (image) => {
        return image.addBands(image.normalizedDifference(['B5', 'B4']).rename('NDVI'));
    };

    // --- Year 1990 (Landsat 5) ---
    const col1990 = ee.ImageCollection('LANDSAT/LT05/C02/T1_L2')
        .filterDate(startDate1, endDate1)
        .filterBounds(areaOfInterest)
        .map(cloudMaskL457)
        .map(addNdviL5);

    const col1990Size = col1990.size().getInfo();
    if (col1990Size === 0) {
        console.log(`Evidence: No images found for ${year1}.`);
        console.log("A: Yes");
        return;
    }
    const image1990 = col1990.select('NDVI').median();

    // --- Year 2019 (Landsat 8) ---
    const col2019 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
        .filterDate(startDate2, endDate2)
        .filterBounds(areaOfInterest)
        .map(cloudMaskL8)
        .map(addNdviL8);

    const col2019Size = col2019.size().getInfo();
    if (col2019Size === 0) {
        console.log(`Evidence: No images found for ${year2}.`);
        console.log("C1");
        return;
    }
    const image2019 = col2019.select('NDVI').median();

    // 3. Calculation & Validation
    const scale = 1000;
    const reducers = ee.Reducer.mean().combine({
        reducer2: ee.Reducer.count(),
        sharedInputs: true
    });

    const stats1990 = image1990.reduceRegion({
        reducer: reducers,
        geometry: areaOfInterest,
        scale: scale,
        maxPixels: 1e9
    }).getInfo();

    const stats2019 = image2019.reduceRegion({
        reducer: reducers,
        geometry: areaOfInterest,
        scale: scale,
        maxPixels: 1e9
    }).getInfo();

    // Check for C2: No Valid Pixels
    if (!stats1990['NDVI_count'] || stats1990['NDVI_count'] === 0 || !stats2019['NDVI_count'] || stats2019['NDVI_count'] === 0) {
        console.log(`Evidence: 1990 Pixel Count: ${stats1990['NDVI_count'] || 0}`);
        console.log(`Evidence: 2019 Pixel Count: ${stats2019['NDVI_count'] || 0}`);
        console.log("C2");
        return;
    }

    const ndvi1990 = stats1990['NDVI_mean'];
    const ndvi2019 = stats2019['NDVI_mean'];

    // Check for C3: Calculation Failure
    if (ndvi1990 === null || ndvi2019 === null || isNaN(ndvi1990) || isNaN(ndvi2019)) {
        console.log(`Evidence: 1990 Mean NDVI: ${ndvi1990}`);
        console.log(`Evidence: 2019 Mean NDVI: ${ndvi2019}`);
        console.log("C3");
        return;
    }

    // 4. Final Answer
    console.log(`Evidence: Image count for 1990: ${col1990Size}`);
    console.log(`Evidence: Image count for 2019: ${col2019Size}`);
    console.log(`Evidence: Mean NDVI in 1990: ${ndvi1990.toFixed(4)}`);
    console.log(`Evidence: Mean NDVI in 2019: ${ndvi2019.toFixed(4)}`);

    if (ndvi2019 < ndvi1990) {
        console.log("A");
    } else {
        console.log("B");
    }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(e => {
    console.error(`An error occurred: ${e}`);
    console.log("D");
});
